window.MUSEUM_CALENDAR={
  "01-01":{t:"Почему Россия стала медведем?",y:"1791",d:"Один и тот же медведь в британском листе 1791 года был и союзником, и чудовищем — менялись только поза и подпись.",href:"day-01jan-russian-bear.html",link:"Открыть расследование →"},
  "01-02":{t:"Наполеон: пришёл за славой — ушёл с носом",y:"1812",d:"Победителя Европы русский лист стёр до карлика: карикатура переписала соотношение сил раньше, чем это сделала армия.",href:"day-02jan-napoleon-slava-nos.html",link:"Открыть расследование →"},
  "01-03":{t:"Радаков: как узнать человека по трём линиям",y:"1877",d:"Радаков выбрасывал лицо целиком — и человека всё равно узнавали: сходство держат силуэт, поза и одна черта.",href:"day-03jan-radakov-tri-linii.html",link:"Открыть расследование →"},
  "01-04":{t:"Почему литография заставила картинку говорить громче",d:"Камень вместо гравюры удешевил оттиск — и смех впервые разошёлся по России тысячами, а не десятками.",href:"day-04jan-litografiya.html",link:"Открыть расследование →"},
  "01-05":{t:"«Крокодил»: как редакция собирала номер",d:"«Крокодил» был не художником, а машиной: редакция решала, над кем смеяться можно, а над кем нельзя.",href:"day-05jan-krokodil-first-issue.html",link:"Открыть расследование →"},
  "01-06":{t:"Кто здесь главный, если убрать подпись?",d:"Власть на карикатуре читается без имён: высота, размер и место в центре выдают начальника быстрее подписи.",href:"day-06jan-who-is-in-charge.html",link:"Открыть расследование →"},
  "01-07":{t:"Портрет, шарж или карикатура?",d:"Портрет показывает, кто перед нами, шарж — как его узнают, а карикатура — что о нём думать.",href:"day-07jan-portrait-sharzh-caricature.html",link:"Открыть расследование →"},
  "01-08":{t:"Как читать карикатуру",d:"Убери из карикатуры контекст — и рисунок соврёт: держат её преувеличение, символ и место публикации."},
  "01-09":{t:"1905 год: журнал на несколько номеров",y:"1905",d:"В 1905 году журнал мог умереть за несколько номеров: цензура решала по названию и намёку, а не по тексту."},
  "01-10":{t:"Европа 1854 года: Россия на полкарты",y:"1854",d:"Россия на карикатурной карте 1854 года раздулась на полкарты: размер показывал не площадь, а чужой страх."},
  "01-11":{t:"Иван Теребенев: художник после события",d:"Теребенев рисовал 1812 год не с поля боя, а с рассказов и донесений — и создал легенду, которую Россия запомнила."},
  "01-12":{t:"Одна картинка — три противоположные подписи",d:"Одна картинка с тремя подписями делает труса осторожным, а хвастуна героем: подпись и есть приговор."},
  "01-13":{t:"Как мыши хоронили кота",d:"Два века зрители видели в похоронах кота похороны царя — легенда оказалась сильнее самого рисунка."},
  "01-14":{t:"Дени и Моор: зачем врага делали смешным",d:"Дени и Моор делали врага смешным до победы: страх уходит, когда противник нарисован жалким."},
  "01-15":{t:"Чиновник: почему стол важнее человека",d:"Бюрократ на карикатуре держится не лицом, а столом: предметы рисуют должность точнее портрета."},
  "01-16":{t:"Силуэт: лицо исчезло, человек остался",d:"Лишённый лица человек остаётся узнаваемым: наклон корпуса, длина шага и форма одежды выдают характер вернее глаз."},
  "01-17":{t:"«Сатирикон»: журнал с несколькими голосами",d:"«Сатирикон» смеялся не одним голосом: обложка, фельетон и реклама на одном развороте делали журнал острым и живым."},
  "01-18":{t:"Лиса, осёл и волк: человеческие пороки в зверях",d:"Лиса хитра ещё до того, как что-то сделала: зверю выдали характер за столетия до карикатуры — а художник может это перевернуть."},
  "01-19":{t:"Один союз — два образа России",y:"1914",d:"В 1914 году один и тот же русский медведь был у немцев варваром, а у англичан союзником: значение задал не зверь, а союз."},
  "01-20":{t:"Где заканчивается сатира и начинается унижение",d:"Карикатура бьёт по решению, власти и пороку — а над происхождением, болезнью и бедой смеяться уже нельзя."},
  "01-21":{t:"Окна РОСТА: комикс на витрине",d:"Окна РОСТА уложили новость в четыре кадра и рифму — прохожий успевал прочитать историю за десять секунд."},
  "01-22":{t:"Какая черта делает человека узнаваемым",d:"Увеличишь все детали сразу — сходство исчезнет: шарж держат одна-две доминанты, а не старательность."},
  "01-23":{t:"Обложка, которая продавала журнал",d:"Обложка продавала номер до того, как читатель открывал страницу — и была голосом журнала, а не украшением."},
  "01-24":{t:"Когда граница превращается в нос, руку или пасть",d:"Карта-карикатура держит форму страны ровно настолько, чтобы страну узнали, — остальное она лепит в нос или пасть."},
  "01-25":{t:"Как сказать «чиновник», не рисуя чиновника",d:"Чиновника можно нарисовать, не рисуя человека: пустой мундир и последствия работают сильнее портрета."},
  "01-26":{t:"Как смеяться вместе с героем",d:"Дружеский шарж смешит привычкой или профессией и не трогает внешность — поэтому его хранят, а не выбрасывают."},
  "01-27":{t:"Бракодел: предмет выдаёт виновника",d:"Кривой стул и разошедшийся ботинок обвиняют сильнее подписи: предмет выдаёт всю цепочку — от мастера до плана."},
  "01-28":{t:"Сатира, агитация или пропаганда?",d:"Сатира оставляет зрителю вопрос, пропаганда выдаёт готовый ответ — приёмы у них одни, разница только в свободе."},
  "01-29":{t:"1812 год: герой в одном зеркале, дикарь в другом",y:"1812",d:"На русском листе 1812 года враг бежит, на французском — русский дикарь: две карикатуры и две разные правды."},
  "01-30":{t:"Один рисунок и тысяча разных отпечатков",d:"Два оттиска с одной доски выглядят как разные листы: краска, давление и ручная раскраска делают экземпляр отдельным."},
  "01-31":{t:"Четыре картинки, четыре эпохи, один неизвестный смысл",d:"Эпоху на карикатуре читают по технике и одежде, а позицию — по масштабу и символам, и подписи для этого не нужны."},
  "02-01":{t:"Гротеск против шаржа",d:"Шарж кусает одного человека, а гротеск — само устройство мира, растягивая тело и логику до жуткого."},
  "02-02":{t:"Капитуляция Паулюса под Сталинградом · 1943",y:"1943",d:"2 февраля 1943 года Паулюс сдался в плен — и советская карикатура сделала пленного фельдмаршала главным героем плакатов."},
  "02-03":{t:"Карикатурная маска (Дени, Моор)",d:"Из живого лица художник лепит маску по одной-двум чертам — и она бьёт точнее портрета и живёт отдельно от прототипа."},
  "02-04":{t:"Псевдонимы сатириков: Дени, Моор, Каран д'Аш",d:"Короткая маска вместо имени — Дени, Моор, Каран д'Аш — била точнее и спасала карикатуриста от расправы."},
  "02-05":{t:"«Шемякин суд» — сатира на суд",d:"Судья в «Шемякином суде» смотрит не в дело, а в шапку с подношением — и Россия смеётся над этим уже столетиями."},
  "02-06":{t:"Борис Кустодиев: шарж купеческой России",d:"Кустодиев знал купеческую Россию изнутри, поэтому даже ядовитый шарж на купца выходил у него тёплым."},
  "02-07":{t:"Цензура: от Николая I до Главлита",d:"Сатиру душили столетие — от самого Николая I до Главлита — а она выжила и продолжала бить исподтишка."},
  "02-08":{t:"День российской науки · 08.02",d:"День российской науки: острый карандаш доставал и учёного с колбой — карикатуристы шутили над наукой во все времена."},
  "02-09":{t:"День стоматолога · 09.02",d:"Кресло, щипцы и застывшая улыбка — бытовой ужас, над которым смеялись до слёз. 9 февраля — день стоматолога, и у карикатуристов на этот счёт запас листов на любой порог боли."},
  "02-10":{t:"Фотомонтаж как оружие сатиры",d:"Ножницы, клей и чужая фотография — и реальный кадр превращается в приговор: фотомонтаж дал сатире XX века убойную силу."},
  "02-11":{t:"Плакат-призыв: палец в грудь",d:"Палец с плаката упирается в грудь — отвечать придётся лично. «Ты записался добровольцем?» Моора стало иконой мирового плаката: вопрос, от которого не спрячешься."},
  "02-12":{t:"Журнал «Смехач» · 1924",y:"1924",d:"Закрыли «Дрезину» — тут же родился «Смехач»: сатирический журнал пережил всех своих цензоров."},
  "02-13":{t:"Обложка сатирического журнала",d:"Обложка рассмешила в киоске раньше, чем читатель купил журнал, — и продавала номер быстрее любого заголовка."},
  "02-14":{t:"День компьютерщика · 14.02",d:"14 февраля 1946 года заработал ENIAC — и карикатуристы получили вечный сюжет: компьютер и его беспомощный пользователь."},
  "02-15":{t:"От лубка к стенгазете",d:"Стенгазета — тот же лубочный приём, только рисует его на заводской стене не гравёр, а умелец из цеха."},
  "02-16":{t:"Карикатура на войне: фронтовой листок",d:"Смех в окопе держал бойца крепче штыка: фронтовой листок, нарисованный под обстрелом, расходился быстрее сводок."},
  "02-17":{t:"Козьма Крючков — герой лубков Первой мировой",d:"Реальный бой Крючкова лубок 1914 года раздул до былины — и вся Россия поверила в первого героя Первой мировой."},
  "02-18":{t:"Лубок русско-японской войны",d:"Лубки 1904–1905 годов рисовали победы, которых не было, и прятали поражения, которые были, — война дошла до народа в последний раз."},
  "02-19":{t:"Отмена крепостного права · 1861",y:"1861",d:"19 февраля 1861 года царь подписал манифест об отмене крепостного права — и «Искра» откликнулась первой же искрой."},
  "02-20":{t:"«Весёлые картинки» — детская карикатура",d:"На «Весёлых картинках» выросла целая страна: журнал впервые собрал карикатуристов ради самых маленьких читателей."},
  "02-21":{t:"Михаил Микешин · 1835–1896",y:"1835",d:"Микешин днём ваял «Тысячелетие России», а по ночам резал сатиру для «Искры» — монумент и карикатура в одном лице."},
  "02-22":{t:"«Крокодил»: символы и рубрики",d:"Красный крокодил с вилами стал гербом советской сатиры: по рубрикам и символам «Крокодила» смешное узнавали с первого взгляда."},
  "02-23":{t:"День Красной армии · 1918",y:"1918",d:"Открытки к 23 февраля — целая летопись улыбки: главный мужской праздник страны вырос из дня рождения Красной армии."},
  "02-24":{t:"Цвет в сатире: от туши к хромолитографии",d:"Хромолитография накладывала краску слоями — и сатира стала цветной, а плакат забил яркостью вывеску."},
  "02-25":{t:"Анатомия мема",d:"Мем — внук карикатуры, которому не нужен художник: те же три ключа — узнавание, преувеличение, подпись."},
  "02-26":{t:"Карикатура как документ эпохи",d:"Рисунок смешил современников, а историку он строгий документ: по деталям листа эпоху датируют точнее, чем по иному указу."},
  "02-27":{t:"Иван Билибин: от сказки к сатире",d:"Билибин тем же пером рисовал и сказочных царевен, и острый политический лист — сатира у него била не слабее сказки."},
  "02-28":{t:"Павел Ассатуров: дореволюционная журнальная карикатура",d:"Ассатуров рисовал для главных сатирических журналов России рубежа веков — и точно знал, над чем смеётся читатель."},
  "03-01":{t:"Убийство Александра II · 1881",y:"1881",d:"Царь-освободитель погиб от бомбы — и следом захлопнулась крышка цензуры."},
  "03-02":{t:"Отречение Николая II · 1917",y:"1917",d:"Империя кончилась за три дня — и журналы взорвались свободой."},
  "03-03":{t:"«Всякая всячина» · 1769",y:"1769",d:"Екатерина II сама завела первый сатирический журнал страны — и учила шутить по-доброму."},
  "03-04":{t:"Журнальная графика: Радаков, Чехонин",d:"Журнальный лист узнавали по линии мастера — ещё до подписи."},
"03-05":{t:"Медведь-диковина: каким зверя видели иноземцы",d:"Медведь начал путь не как политика, а как диковина: западные гравюры рисовали далёкую Московию через мороз, шубу и зверя."},
  "03-06":{t:"«Почта духов» · 1789",y:"1789",d:"Крылов заставил духов писать письма о людских пороках — и спрятал сатиру за сказку."},
  "03-07":{t:"«Ералаш» · 1846",y:"1846",d:"Первый журнал, где смех был нарисован, а не написан."},
  "03-08":{t:"Международный женский день",d:"«Крокодил» годами рисовал 8 марта женщин — тружениц, красавиц, хозяек."},
  "03-09":{t:"«Калека и Смерть» — лубок",d:"Нищий и Смерть спорят, кому хуже, — и народ хохочет над страшным."},
  "03-10":{t:"Шарж среди своих",d:"Шарж среди своих — не укус, а рукопожатие карандашом."},
  "03-11":{t:"Избрание Горбачёва · 1985",y:"1985",d:"Началась перестройка — и сатире разрешили то, что тридцать лет было нельзя."},
  "03-12":{t:"«Искра» · 1859",y:"1859",d:"Журнал бил по крепостному праву карикатурой — власти закрывали, читатели прятали."},
  "03-13":{t:"Шарж «Сатирикона»: Радаков",d:"Шарж «Сатирикона» бил острее передовицы."},
  "03-14":{t:"«Гудок» · 1862",y:"1862",d:"Сатира свистела как паровоз по чиновникам — журнал прикрыли за год."},
  "03-15":{t:"«Ерошка» — балаганный лубок",d:"Народный шут говорил царям на лубке то, что нельзя было вслух."},
  "03-16":{t:"НЭП · 1921",y:"1921",d:"Власть разрешила торговать — и сатира тут же нарисовала нэпмана."},
  "03-17":{t:"«Будильник» · 1865",y:"1865",d:"Журнал будил страну смехом шесть десятилетий — пережил и цензуру, и смену власти."},
  "03-18":{t:"«Бабья бунт» — лубок",d:"Бабы дерутся из-за мужика — и вся деревня хохочет."},
  "03-19":{t:"Бытовой жанр: сатира на нравы",d:"Мещанин, купец и чиновник за обедом — сатира мирного времени."},
  "03-20":{t:"Русская пословица в карикатуре",d:"«Без труда не выловишь и рыбку из пруда» — в одном рисунке."},
  "03-21":{t:"Сатирический портрет: Дени",d:"Дени лепил из политика типаж — узнаваемый с одного взгляда."},
  "03-22":{t:"Николай Радлов · 1889–1942",y:"1889",d:"Его карикатура осталась тёплой даже в страшное время."},
  "03-23":{t:"Театральный шарж: маска в квадрате",d:"Актёр на сцене — маска, а в шарже — маска в квадрате."},
  "03-24":{t:"«Стрекоза» · 1875",y:"1875",d:"В «Стрекозе» дебютировал молодой Чехов — трамплин для главных имён."},
  "03-25":{t:"Карикатура в детской книге",d:"Ребёнка не обманешь фальшью — детская карикатура строже взрослой."},
"03-26":{t:"Медведь на цепи: народная потеха и лубок",d:"Медведь с поводырём был живым промыслом и героем народной картинки — политического смысла в нём ещё нет."},
  "03-27":{t:"Карикатура в рекламе",d:"Смешной рисунок продавал быстрее длинного текста."},
  "03-28":{t:"Юрий Арцыбушев · 1877–1952",y:"1877",d:"Редактор «Зрителя» сам рисовал, пока цензор не отнял кисть."},
  "03-29":{t:"Детский шарж: Радлов",d:"Его детский шарж смешил и детей, и взрослых."},
  "03-30":{t:"Карикатура на марке и конверте",d:"Смешной рисунок улетал на конверте по всей стране."},
  "03-31":{t:"Политический шарж вождей",d:"От Ленина до Брежнева — вождей рисовали осторожно, но метко."},
  "04-01":{t:"День смеха",d:"Первое апреля — единственный день, когда высмеять можно всё, и карикатура ждёт его весь год."},
  "04-02":{t:"«Осколки» · 1881",y:"1881",d:"Будущий классик прятался в «Осколках» под маской Антоши Чехонте и начинал с короткой сатиры."},
  "04-03":{t:"Алексей Радаков · 1877–1942 · привязка: первый номер «Сатирикона» 3.04.1908",y:"1877",d:"Радаков вместе с Аверченко придумал «Сатирикон» и нарисовал его первую обложку — с неё начался смех Серебряного века."},
  "04-04":{t:"«Апрельские тезисы» Ленина · 1917",y:"1917",d:"Возвращение Ленина в апреле 1917-го раскололо страну — и карикатура всех лагерей взорвалась в один день."},
  "04-05":{t:"Политический плакат: Моор",d:"Политический плакат Моора бил наотмашь — одна фигура, один лозунг, один удар."},
  "04-06":{t:"Лубок «Медведь и поп» — антиклерикальный",d:"На лубке медведь и поп выясняют, кому от кого бежать, — и народ смеётся над церковью."},
  "04-07":{t:"«Фитиль» — сатира в кино",d:"«Фитиль» смешил страну перед каждым фильмом — и зритель узнавал правду, которую не печатали."},
  "04-08":{t:"Лубок «Прения жениха с невестой» — свадебная сатира",d:"Свадьба на лубке — не торжество, а спор двух сторон о том, кто кого берёт."},
  "04-09":{t:"Анекдот рядом с рисунком",d:"Рисунок и анекдот спорят за смех — а вместе бьют сильнее."},
  "04-10":{t:"«Развлечение» · 1859–1916",y:"1859",d:"«Развлечение» прожило полвека и пережило трёх императоров — сатира держалась там, где другие тонули."},
  "04-11":{t:"Сатира в театре: миниатюры Райкина",d:"Райкин одним жестом говорил то, что не могли напечатать, — сцена была смелее бумаги."},
  "04-12":{t:"Полёт Гагарина · 1961",y:"1961",d:"Гагарин вышел в космос — и «Крокодил» тут же нарисовал космонавтов, спутников и инопланетян."},
  "04-13":{t:"Автопортрет карикатуриста",d:"Автопортрет сатирика — исповедь и очередная маска одновременно."},
  "04-14":{t:"Журнальный шарж: Дени",d:"Штрих Дени узнавали и в «Крокодиле», и в книжной классике — его линия жила и в сатире, и в лирике."},
  "04-15":{t:"Дружеский шарж: Щербов",d:"Щербов рисовал артистов и поэтов так, что те просили «ещё», — шарж оборачивался комплиментом."},
  "04-16":{t:"Лубок «Лечение иноземца» — антинемецкие лубки",d:"Лубок «лечил» немца от жадности и спеси — и рисовал чужого, чтобы сказать о своих."},
  "04-17":{t:"Сатира в эмиграции",d:"Русские сатирики после 1917-го продолжали смеяться — но уже с чужого берега."},
  "04-18":{t:"«Шут» · 1879–1914",y:"1879",d:"«Шут» с говорящим названием шутил с империей тридцать пять лет и пережил смену эпох."},
  "04-19":{t:"Лубок о моде: «щёголь» и щёгольская лавка",d:"Лубок высмеивал франта, одетого «по-столичному», — деревня смеялась над модой как над чужаком."},
  "04-20":{t:"Карикатура на выставке",d:"Карикатура уходит с полосы на музейную стену — и зритель решает, искусство это или оружие."},
  "04-21":{t:"Лубок «Паровоз-чудо» — лубок железной дороги",d:"Лубок смотрел на паровоз как на диковину и угрозу сразу — прогресс пугал и смешил."},
  "04-22":{t:"Самиздатская карикатура",d:"Когда печать закрыли, смех ушёл подпольно — в копии из рук в руки."},
  "04-23":{t:"Театральный шарж: Радлов",d:"Радлов шаржировал сцену так, что жест актёра был виден без подписи."},
  "04-24":{t:"Объявление русско-турецкой войны 1877–78",d:"Война за Балканы началась — и «Стрекоза» с лубком одели её в карикатуру ещё до первых боёв."},
  "04-25":{t:"«Звонок» · 1905",y:"1905",d:"Журнал-однодневка 1905 года успел прозвенеть — и замолчал."},
  "04-26":{t:"Лубок «Смерть и старуха» — сатира на скупость",d:"Смерть приходит к скупой старухе — а та торгуется за последний грош."},
  "04-27":{t:"Карикатурист-одиночка против редакции",d:"Художник против главного редактора — спор о том, что можно и что нельзя печатать."},
  "04-28":{t:"Бытовой шарж: Кустодиев",d:"Кустодиев рисовал купеческую Россию с любовью и смехом — шарж без яда."},
  "04-29":{t:"Итог года в карикатуре",d:"В конце года журналы рисовали «итоги» — и это был портрет эпохи, где смех — хроника."},
  "04-30":{t:"Праздничный лубок: масленица и святки",d:"Лубок рисовал праздник, где всё разрешено наоборот, — и мир переворачивался на один день."},
  "05-01":{t:"1 Мая — праздник весны и труда",d:"Праздник, который сначала запрещали, сатира проводила сто лет — до первомайских обложек «Крокодила»."},
  "05-02":{t:"Лубок «Баба мужа боронит» — перевёрнутый мир",d:"Жена уходит на охоту, муж садится за прялку — народная картинка переворачивает мир и смеётся над порядком."},
  "05-03":{t:"Николай Степанов · 1807–1877",y:"1807",d:"Художник Степанов издал «Искру» и «Будильник» — с этих журналов началась русская журнальная карикатура."},
  "05-04":{t:"«Сатира в эпоху без сатиры» — крокодильская улыбка",d:"Систему ругать нельзя, а «Крокодил» выходил каждую неделю — журнал шутил между строк, не называя вещей своими именами."},
  "05-05":{t:"Лубок «Пьяница» — антиалкогольный",d:"Пьяница на лубке теряет дом, деньги и лицо — народная картинка лечила смехом то, о чём не говорили вслух."},
  "05-06":{t:"Карикатура в агитпоезде и агитпароходе",d:"Газеты не доезжали до деревни — сатира села в поезд и поплыла по реке к тем, кто читать не умел."},
  "05-07":{t:"День радио",d:"Голос в эфире казался чудом — у радиоприёмника сатира смеялась и над связью, и над теми, кто ей верил."},
  "05-08":{t:"Журнал «Жупел» · 1905",y:"1905",d:"Билибин, Добужинский и Лансере рисовали революцию в «Жупеле» — трёх номеров хватило, чтобы журнал закрыли."},
  "05-09":{t:"День Победы · 1945",y:"1945",d:"Кукрыниксы нарисовали Гитлера, теряющего «колечко» из окружённых армий, ещё до Победы — смех воевал и встретил конец войны."},
  "05-10":{t:"Сатира на съезде: карикатурист при делегатах",d:"Художник с блокнотом в президиуме вёл рисованную хронику съезда — шарж видел в делегатах то, что не говорили с трибуны."},
  "05-11":{t:"Лубок «Взятие крепости» — военная небылица",d:"Лубок нарисовал взятие крепости, которого не было, — с пушками, дымом и героем, чтобы война стала своей победой."},
  "05-12":{t:"Журнал «Пулемёт» · 1905",y:"1905",d:"«Пулемёт» посмел изобразить царя на обложке — и журнал уничтожили, а грань дозволенного стала видна всем."},
  "05-13":{t:"Лубок «Варяжский гость» — образ врага",d:"Один и тот же чужеземец на лубке — то гость, то враг: война меняла знак фигуры за один день."},
  "05-14":{t:"Цусимское сражение · 1905",y:"1905",d:"Разгром эскадры потряс страну — сатира ответила раньше газет и объяснила поражение, о котором молчали сводки."},
  "05-15":{t:"Сатира провинции: городские листки",d:"Уездные листки рисовали своих чиновников и купцов — провинция смеялась над теми, кого столица не знала в лицо."},
  "05-16":{t:"Журнал «Зритель» · 1905",y:"1905",d:"«Зритель» закрыли за одну карикатуру — и журнал стал символом риска, который запомнился сильнее выживших."},
  "05-17":{t:"Лубок о городовых и полицейских",d:"Городовой на лубке — то блюститель, то взяточник: народная картинка говорила о власти то, что боялась сказать вслух."},
  "05-18":{t:"Николай Чехов · 1858–1889",y:"1858",d:"Брат писателя рисовал для «Осколков» и умер молодым — его подпись ценили не меньше чеховской прозы."},
  "05-19":{t:"Спортивный шарж: Олимпиада-80",d:"Мишка-талисман и спортсмены в шарже — сатира рисовала Олимпиаду, которой гордились, с улыбкой, а не с ядом."},
  "05-20":{t:"Карикатура в телеграмме эпохи",d:"До телевидения новость шла по проводам — сатира тоже, и рисунок добирался до читателя раньше газеты."},
  "05-21":{t:"Лубок «Ссора Ивана с Иваном» — бытовая сатира",d:"Два Ивана не поделили пустяк — народная картинка смеётся над обоими и показывает, из чего растут большие ссоры."},
  "05-22":{t:"Грим и маска в карикатуре",d:"Нос, брови, усы — карикатурист гримирует героя под типаж, пока сходство не становится маской."},
  "05-23":{t:"Советский нонконформизм",d:"Когда официоз нельзя было критиковать открыто, смех ушёл в коллаж и подпись — нонконформизм взламывал систему изнутри."},
  "05-24":{t:"Журнал «Бегемот» · 1924",y:"1924",d:"Ленинградский «Бегемот» спорил с московским «Крокодилом» — у двух столиц оказался разный смех."},
  "05-25":{t:"«Скалозуб» и типажи: литературные маски в рисунке",d:"Литературный типаж — от Скалозуба до журнальной маски — оживает в карикатуре нагляднее, чем в тексте."},
  "05-26":{t:"Михаил Знаменский · 1833–1892",y:"1833",d:"Карикатурист и краевед Знаменский смеялся над сибирскими нравами — уездный художник видел их острее столичных."},
  "05-27":{t:"Политическая сатира: Моор",d:"Политическая сатира Моора рисовала врага так, что он оставался страшен — и всё-таки смешон."},
  "05-28":{t:"Шарж как награда: «крокодильская» премия юмора",d:"Шарж в сатирическом журнале был не обидой, а наградой — попасть в него значило, что тебя заметили."},
  "05-29":{t:"Суд над журналом: процессы «Сатирикона»",d:"Журнал судили за смех — и каждый процесс становился рекламой, а запрет только разгонял тираж."},
"05-30":{t:"Русский медведь в журнальной сатире XIX века",d:"Журналы размножили образ: один и тот же медведь по-разному выглядел у разных изданий — в Европе и в России."},
  "05-31":{t:"Шарж в прессе: Радлов",d:"Шарж Радлова в прессе узнавали с одного взгляда — его линия делала смех мгновенным."},
  "06-01":{t:"День защиты детей",d:"Детский смех — самый честный: сатира рисовала и детей, и для детей, от «Весёлых картинок» до первой шалости в тетради."},
  "06-02":{t:"Лубок «Враки-басни» — сатирические подписи",d:"Народная картинка притворялась небылицей, а говорила правду — под «враки» прятали то, что не смели сказать вслух."},
  "06-03":{t:"Журнал «Чудак» · 1928–1931",y:"1928",d:"Журнал Ильфа и Петрова смеялся над временем — и его закрыли за шутку, которая оказалась точнее газетной сводки."},
  "06-04":{t:"Лубок «Чёртова качеля» — чертовщина",d:"Нечистая сила в лубке смешна, а не страшна — чертей рисовали, чтобы посмеяться над теми, кто ими пугает."},
  "06-05":{t:"Журнальная заставка и виньетка",d:"Рисованная «шапка» журнала говорила больше заголовка — виньетка сразу называла, над кем будет смеяться номер."},
  "06-06":{t:"Пушкинский день · 1799",y:"1799",d:"Пушкина рисовали и другом, и бунтарём — за двести лет карикатура перекраивала его лицо под каждую эпоху."},
  "06-07":{t:"Лубок «Диво чудное» — невидаль",d:"Народная картинка выдумывала невозможное — и за хвостами и крыльями прятала смех над самой жизнью."},
  "06-08":{t:"Журнал «Адская почта» · 1906",y:"1906",d:"Журнал с «адским» названием прожил недолго — цензура закрыла его за лист, который называл вещи по имени."},
  "06-09":{t:"Лубок о чиновнике и просителе",d:"Задолго до «Ревизора» лубок нарисовал чиновника, который берёт, — смех опередил литературу на полвека."},
  "06-10":{t:"«Крокодил» за границей — переводы и отклики",d:"Советскую сатиру читали в мире — и в переводе терялось главное, из-за чего смеялись иностранцы."},
  "06-11":{t:"Лубок «Табак» и «Вино» — парные нравоучительные",d:"Лубок лечил от пьянства и курения смехом — парные листы показывали, куда ведут вредные привычки."},
  "06-12":{t:"День России · 1990",y:"1990",d:"Художники смеются над собственным государством — самоирония оказалась вернее казённого пафоса."},
  "06-13":{t:"«Адресная» сатира лубка: Лондон, Париж, Туреччина",d:"Народная картинка знала географию врага лучше учебника — на лубочной карте враг был подписан поимённо."},
  "06-14":{t:"Журнал «Сигнал» · 1905 (Корней Чуковский)",y:"1905",d:"Корней Чуковский начинал с политической сатиры — детский сказочник сначала редактировал журнал, который закрыли."},
  "06-15":{t:"Павел Щербов · 1866–1938",y:"1866",d:"«Русский Домье» рисовал так, что его листов боялись министры — сатира Щербова колола точнее слов."},
  "06-16":{t:"Полёт Валентины Терешковой · 1963",y:"1963",d:"Первая женщина в космосе — карикатура встретила полёт, которым гордились, и всё равно улыбнулась."},
  "06-17":{t:"«Умный» лубок — ребусы и загадки в картинках",d:"Народная картинка играла с читателем — ребус прятал насмешку, которую цензор не мог прочитать."},
  "06-18":{t:"Журнал «Новый Сатирикон» · 1913",y:"1913",d:"После раскола родился «Новый Сатирикон» — смех повзрослел и стал бить по политике в упор."},
  "06-19":{t:"Гротеск и аллегория: Александр Зальцман",d:"Гротеск Зальцмана доводил портрет до маски — аллегория рисовала порок, который узнавали без подписи."},
  "06-20":{t:"Журнальная сатира быта: Давид Видгоф",d:"Видгоф рисовал быт и нравы так, что тип не устарел за сто лет — купец, чиновник и обыватель остались те же."},
  "06-21":{t:"Рукописная картинка раскольников — прото-лубок",d:"До печатного лубка запрещённую картинку рисовали от руки — сатира ходила из рук в руки втайне от власти."},
  "06-22":{t:"Начало Великой Отечественной войны · 1941",y:"1941",d:"В первый день войны Кукрыниксы выпустили плакат «Беспощадно разгромим…» — смех стал оружием за один день."},
  "06-23":{t:"Издатели лубка: Сытин и акционерные издательства",d:"Сытин поставил смех на поток — лубок был и народным искусством, и бизнесом с миллионными тиражами."},
  "06-24":{t:"Пётр Боклевский · 1816–1897",y:"1816",d:"Его Чичиков и Собакевич стали лицами «Мёртвых душ» — один художник закрепил сатиру Гоголя навсегда."},
  "06-25":{t:"Календарь сатиры — как музей считает год смехом (мета-день)",d:"Полгода смеха позади — карикатура успела рассказать о времени больше, чем иная летопись."},
  "06-26":{t:"Карикатура и психиатрия",d:"Психиатры и карикатуристы смотрят в одно зеркало — смех лечит и рисует то, о чём трудно говорить вслух."},
  "06-27":{t:"Лубок о крепостном театре",d:"Крепостной театр был роскошью бар — лубок смеялся над теми, кто играл, и над теми, кто заставлял."},
  "06-28":{t:"Бытовая сатира: Александр Нотбек",d:"Нотбек рисовал быт «Искры» — в его листе обыватель узнавал себя и смеялся, не подозревая подвоха."},
  "06-29":{t:"Журнал «Шершень» · 1906",y:"1906",d:"Журнал жалил власть в 1906-м — «Шершень» прожил недолго, но его жало запомнили все."},
  "06-30":{t:"Лубок о «новых людях» петровской эпохи",d:"Пётр менял страну, а лубок смеялся над бритыми бородами — реформа стала шуткой раньше, чем законом."},
  "07-01":{t:"Оскар Шмерлинг · 1863–1938",y:"1863",d:"Шмерлинг привёз карикатуру на Кавказ — и его листы засмеялись сразу на трёх языках."},
  "07-02":{t:"Театральный шарж: как нарисовать роль",d:"Театральный шарж ловит не лицо, а роль — сцена смеётся над человеком вернее, чем зал."},
  "07-03":{t:"«Русский сатирический листок» · 1858",y:"1858",d:"В 1858-м смех впервые стал отдельным изданием, а не рубрикой — листок прожил коротко, но сказал многое."},
  "07-04":{t:"Лубки по басням Крылова",d:"Басни Крылова народ читал по картинкам — лубок превращал мораль в уличную сценку."},
  "07-05":{t:"Начало Курской битвы · 1943",y:"1943",d:"Пока танки сходились под Курском, сатира уже считала врага по головам — карикатура воевала рядом с армией."},
  "07-06":{t:"Михаил Невахович · 1817–1850",y:"1817",d:"Невахович придумал первый русский сатирический журнал с картинками — и умер в тридцать три."},
  "07-07":{t:"Детский лубок и азбука в картинках",d:"Азбука в картинках учила деревню читать — и смешить одновременно."},
  "07-08":{t:"День семьи, любви и верности",d:"Муж и жена, тёща и зять — семейный быт был вечным сюжетом сатиры, не выходя из дома."},
  "07-09":{t:"«Заноза» · 1905",y:"1905",d:"Журнал с именем-укусом родился в год революции — и жалил сильнее рисунком, чем текстом."},
  "07-10":{t:"Лубок о Наполеоне-«небывальщине» · 1812–1814",y:"1812",d:"Лубок превратил непобедимого императора в карлика-небылицу — смех оказался сильнее страха."},
  "07-11":{t:"Тиражная графика: литография против цензуры",d:"Пока цензор читал текст, литография печатала рисунок тысячами — техника опережала запрет."},
  "07-12":{t:"День рыбака",d:"Главный трофей рыбака — «во-о-от такая» рыба: сатира веками рисовала удочку, улов и размах рук."},
  "07-13":{t:"«Француз и крестьянин» — лубки 1812 года",d:"Патриотический лубок рисовал войну как спор француза с русским мужиком — и мужик всегда выходил победителем."},
  "07-14":{t:"«Лукоморье» · 1914",y:"1914",d:"Журнал, открывшийся в год Первой мировой, — сатира жила на войне, когда смеяться становилось страшно."},
  "07-15":{t:"Роберт Черняк · 1900–1932",y:"1900",d:"Черняку судьба отпустила тридцать два года — но его лист запомнили."},
  "07-16":{t:"Михаил Линский · 1878–1941",y:"1878",d:"Линский рисовал Россию на сломе эпох — его лист говорит о времени, которое он сам не пережил."},
  "07-17":{t:"Детская карикатура: как смешить ребёнка",d:"Детская карикатура смешит не злостью, а узнаванием — ребёнок смеётся, узнав себя."},
  "07-18":{t:"«Красный ворон» · 1922",y:"1922",d:"Предшественник «Бегемота», где сатира искала свой красный цвет, — и накаркала себе закрытие."},
  "07-19":{t:"День металлурга",d:"Карикатура рисовала завод и его героев с особым теплом — плавка, бригада, соцсоревнование."},
  "07-20":{t:"Политическая сатира без подписи",d:"Политическая сатира без подписи понятна с одного взгляда — лицо говорит громче текста."},
  "07-21":{t:"Портрет-шарж: одной линией",d:"Портрет-шарж оставляет от человека одну черту — и по ней узнаётся всё лицо."},
  "07-22":{t:"Что такое шарж",d:"Шарж — не просто большой нос: одна линия ловит суть человека до карикатуры."},
  "07-23":{t:"«Прожектор» · 1923",y:"1923",d:"Единственный многокрасочный сатирический журнал страны — цвет усиливал удар смеха."},
  "07-24":{t:"«Синяя блуза» и агит-лубок 1920-х",d:"«Живая газета» играла новости в синих блузах — агит-сатира 1920-х унаследовала лубочный размах."},
  "07-25":{t:"Лубок «на грани»: заветные картинки",d:"Лубок знал сюжеты, которые не печатали в газетах, — и обходил цензуру приличий."},
  "07-26":{t:"День ВМФ",d:"Тельняшка, кортик, якорь — герои тысяч карикатур: сатира рисовала море и тех, кто по нему ходит."},
  "07-27":{t:"Михаил Дризо · 1887–1953",y:"1887",d:"Карикатурист «Сатирикона» пережил журнал и эпоху — его лист пережил всё, что рисовал."},
  "07-28":{t:"«Капкан» · 1925",y:"1925",d:"Чувашский журнал сатиры прожил почти век — смех звучал на языке, который редко слышали в столицах."},
  "07-29":{t:"Русская карикатура глазами иностранца",d:"Как нас рисовали со стороны и как мы отвечали на чужой взгляд — иностранец видел стереотип, мы — правду."},
  "07-30":{t:"Лубок о «разделе» — грабёж как сюжет",d:"Лубок рисовал разбой и делёж, не романтизируя, а пугая, — и лечил страх смехом."},
  "07-31":{t:"«Ералаш» — киножурнал детской сатиры",d:"Детский киножурнал, на котором выросла страна, — смеяться вместе с детьми оказалось труднее, чем над взрослыми."},
  "08-01":{t:"Начало Первой мировой войны · 1914",y:"1914",d:"Россия вступила в войну — и карикатура в тот же день встала в строй."},
  "08-02":{t:"День ВДВ",d:"День десантника: карикатура всегда рисовала голубой берет с гордостью — и с улыбкой."},
  "08-03":{t:"Иван Грабовский · 1878–1922",y:"1878",d:"Грабовский смешил сатирические журналы на рубеже веков — от смеха остался почерк мастера."},
  "08-04":{t:"«Колотушка» · 1911",y:"1911",d:"Журнал «Колотушка» бил по нравам изнутри — и наколотил себе короткую жизнь."},
  "08-05":{t:"Лубок о суде и взятке",d:"Лубок рисовал суд кривым, а взятку жирной — смеялся над тем, чего боялся."},
  "08-06":{t:"Яков Бельский · 1897–1937",y:"1897",d:"Бельский рисовал для советской печати — его лист спорил с передовицей и побеждал смехом."},
  "08-07":{t:"Яков Струхманчук · 1884–1937",y:"1884",d:"Струхманчук вёл сатирический рисунок — его лист держал читателя точнее слова."},
  "08-08":{t:"День физкультурника",d:"День физкультурника: турник, норматив и свисток стали сюжетом — сатира смеялась, но гордилась."},
  "08-09":{t:"День строителя",d:"День строителя: кран, бригада и раствор — карикатура рисовала стройку с теплом и кирпичом."},
  "08-10":{t:"Андрей Лейферт · 1898–1937",y:"1898",d:"Лейферт рисовал для журналов — его карикатура шла к читателю раньше передовицы."},
  "08-11":{t:"Семён Зальцер · 1898–1941",y:"1898",d:"Зальцер одной линией ловил суть человека — его шарж узнавался без подписи."},
  "08-12":{t:"Юмористическая открытка",d:"Открытку с праздником и смехом слали по почте — карточка сама стала листом сатиры."},
  "08-13":{t:"Иван Малютин · 1891–1932",y:"1891",d:"Малютин рисовал быт и нравы — его сатира смеялась над тем, что всех касалось."},
  "08-14":{t:"«Мухомор» · 1906",y:"1906",d:"Журнал «Мухомор» родился в год первой революции — и успел отравить, прежде чем закрыли."},
  "08-15":{t:"Сатирическая кукла и чучело",d:"Карнавал нёс кукол-шаржей и жёг чучела — сатира вышла из бумаги в объём."},
  "08-16":{t:"День Воздушного флота",d:"День Воздушного флота: самолёт, шлем и облака — карикатура рисовала крылатых с романтикой."},
  "08-17":{t:"«Леший» · 1906",y:"1906",d:"Журнал «Леший» жалил власть в 1906-м — прожил недолго, а ужалил больно."},
  "08-18":{t:"Серийный типаж сатиры",d:"Один персонаж кочевал из номера в номер — сатира лепила сквозного героя эпохи."},
  "08-19":{t:"Августовский путч (ГКЧП) · 1991",y:"1991",d:"Три дня страна замерла у телевизора — карикатура ответила на излом эпохи мгновенно."},
  "08-20":{t:"«Кнут» · 1906",y:"1906",d:"Журнал «Кнут» бил по власти с размаха — и высек себе закрытие."},
  "08-21":{t:"Сатирический киноплакат",d:"Афиша к комедии смешила раньше фильма — киноплакат сам стал карикатурой."},
  "08-22":{t:"День Государственного флага России · 1994",y:"1994",d:"День триколора: флаг и цвета стали сюжетом — сатира шутит о серьёзном символе бережно."},
  "08-23":{t:"«Пушка» (газета) · 1917",y:"1917",d:"Газета «Пушка» выстрелила в год революции — печатная сатира била по самому больному."},
  "08-24":{t:"Журнальный ребус и загадка",d:"Читатель разгадывал рисунок как шифр — сатира прятала второй смысл в ребусе."},
  "08-25":{t:"«Вампир» · 1905",y:"1905",d:"Журнал «Вампир» сосал кровь из власти в год революции — рисунок жалил сильнее текста."},
  "08-26":{t:"Карикатура на юбиляра (адрес-альбом)",d:"К юбилею дарили альбом шаржей — насмешка стала подарком."},
  "08-27":{t:"День российского кино · 1919",y:"1919",d:"День кино: афиша, проектор и зритель — сатира рисовала тех, кто смешит с экрана."},
  "08-28":{t:"«Красный перец» · 1922",y:"1922",d:"Журнал «Красный перец» смешил в первые годы советской власти — и успел поперчить."},
  "08-29":{t:"Мульт-сатира",d:"Неподвижный шарж ожил и задвигался — анимация дала смеху движение."},
  "08-30":{t:"День шахтёра",d:"День шахтёра: забой, бригада и каска — карикатура рисовала тех, кто достаёт уголь."},
  "08-31":{t:"Карикатура в стенгазете",d:"Стена завода и школы была самой близкой сценой сатиры — шарж жил на доске объявлений."},
  "09-01":{t:"День знаний",d:"Первый звонок — карикатура встречает школу с бантом, портфелем и букварём."},
  "09-02":{t:"Пожар Москвы · 1812",y:"1812",d:"Москва сгорела — карикатура первая нарисовала Наполеона беглецом."},
  "09-03":{t:"Лев Бродаты · 1889–1954",y:"1889",d:"Бродаты печатали главные газеты страны — политика под его пером становилась рисунком."},
  "09-04":{t:"Евгений Лансере · 1875–1946",y:"1875",d:"Лансере рисовал для «Жупела» и «Адской почты» — его линия стала языком сатиры 1905-го."},
  "09-05":{t:"Дмитрий Кардовский · 1866–1943",y:"1866",d:"Кардовский начал с сатирического рисунка — шарж наточил руку будущего академика."},
  "09-06":{t:"День нефтяника",d:"Вышка, каска и чёрное золото — карикатура рисовала нефтяников с гордостью и улыбкой."},
  "09-07":{t:"Бородинское сражение · 1812",y:"1812",d:"Бородино дало карикатуре главный заказ — рисовать Наполеона маленьким."},
  "09-08":{t:"Начало блокады Ленинграда · 1941",y:"1941",d:"Ленинград в кольце — а «Боевой карандаш» продолжал рисовать."},
  "09-09":{t:"«Бузотёр» · 1924",y:"1924",d:"Журнал с именем-скандалом смешил Ленинград 1920-х — и успел «набузить» до закрытия."},
  "09-10":{t:"Мем и карикатура",d:"Мем — карикатура сетевой эпохи: картинка с подписью бьёт быстрее газетной полосы."},
  "09-11":{t:"Убийство Столыпина · 1911",y:"1911",d:"Сатира провожала Столыпина при жизни — и после выстрела Богрова."},
  "09-12":{t:"Александр Воронецкий · 1885–1929",y:"1885",d:"Воронецкий работал на сломе веков — его рисунок совместил старую журнальную школу с новой злостью."},
  "09-13":{t:"День программиста",d:"Баг, монитор и дедлайн — карикатура рисует айтишников с гордостью и улыбкой."},
  "09-14":{t:"Моисей Ваксер · 1916–1942",y:"1916",d:"Ваксер погиб на войне — его лист успел сказать главное."},
  "09-15":{t:"Константин Гримм · 1845–1896",y:"1845",d:"Гримм рисовал власть без лести — его шарж бил точнее передовицы."},
  "09-16":{t:"«Крокодильская улыбка»: сатира позднего СССР",d:"Когда шутить было опасно, «Крокодил» прятал второй смысл между строк."},
"09-17":{t:"Медведь Холодной войны и Олимпиады-80",d:"Один век — два облика: на Западе грозный символ СССР, дома добрый талисман Олимпиады."},
  "09-18":{t:"«Смех» · 1924",y:"1924",d:"Московский журнал со смелым именем смешил 1920-е — цензор унял его не сразу."},
  "09-19":{t:"Шарж оживает",d:"Кадр за кадром рисунок задышал: мультфильм дал карикатурному герою время и голос."},
  "09-20":{t:"Пародийный портрет: «вожди» в рисунке",d:"Шарж на власть — самая опасная граница сатиры: где смех, а где приговор."},
  "09-21":{t:"Иван Каликин · 1884–1941",y:"1884",d:"Каликин рисовал на рубеже двух эпох — и оборвался в 1941-м."},
  "09-22":{t:"Иосиф Роттер · 1867–1937",y:"1867",d:"Роттер рисовал время перемен — его сатира ловила суть человека одной линией."},
  "09-23":{t:"«Оса» · 1906",y:"1906",d:"«Оса» жалила власть в год первой революции — и была прихлопнута."},
  "09-24":{t:"Григорий Розе · 1900–1942",y:"1900",d:"Розе рисовал политический плакат — его лист бил по врагу раньше передовицы."},
  "09-25":{t:"Артюр Бартельс · 1818–1885",y:"1818",d:"Бартельс ловил смешное в будничном — там, где другой проходил мимо, он видел готовый сюжет."},
  "09-26":{t:"Магда Нахман · 1889–1951",y:"1889",d:"Нахман рисовала добрый шарж — её портрет узнавался без подписи."},
  "09-27":{t:"Иван Всеволожский · 1835–1909",y:"1835",d:"Всеволожский рисовал лица эпохи — его портрет жалил точнее сплетни."},
  "09-28":{t:"Илья Павиль · 1873–1944",y:"1873",d:"Павиль рисовал сатирическую графику — его лист бил по нравам точнее проповеди."},
  "09-29":{t:"Францишек Костжевский · 1826–1911",y:"1826",d:"Костжевский рисовал портретный шарж — лицо под его пером выдавало характер."},
  "09-30":{t:"Концептуальная графика",d:"Концепция вышла из карикатуры — рисунок заговорил без слов."},
  "10-01":{t:"Старт первой пятилетки · 1928",y:"1928",d:"Стартовал первый пятилетний план — «Крокодил» тут же нарисовал бюрократов и лодырей у станка."},
  "10-02":{t:"Всемирный день улыбки",d:"Весь мир улыбается по расписанию — а карикатура улыбалась всегда, без выходных."},
  "10-03":{t:"Сергей Чехонин · 1878–1936",y:"1878",d:"Мирискусник Чехонин расписал агитационный фарфор — изысканная линия стала оружием сатиры."},
  "10-04":{t:"Запуск первого спутника · 1957",y:"1957",d:"Крошечный шар вышел на орбиту — и карикатура взмыла в космос вместе с ним."},
  "10-05":{t:"День учителя",d:"Доска, указка, двойка в дневнике — карикатура века рисовала класс без прикрас."},
  "10-06":{t:"Сергей Светославский · 1857–1931",y:"1857",d:"Пейзажист Светославский начинал с сатирического рисунка — шарж наточил руку будущего мастера."},
  "10-07":{t:"«Раёк и раёшник» — уличная сатира",d:"Уличный «телевизор» XIX века — картинки на верёвочке под острый стих раёшника."},
  "10-08":{t:"Сатирический портрет: сила одной черты",d:"Сатирический портрет оставляет от лица одну черту — и человека узнаёшь мгновенно."},
  "10-09":{t:"Всемирный день почты",d:"Конверт, марка, очередь — карикатура отправилась в путь по всей стране вместе с письмом."},
  "10-10":{t:"«Бич» · 1905",y:"1905",d:"Журнал «Бич» хлестал власть в год первой революции — и был прихлопнут цензором."},
  "10-11":{t:"Виктор Дени · 1893–1946",y:"1893",d:"Виктор Денисов превратил плакат в оружие — и рисовал им целую эпоху."},
  "10-12":{t:"Наполеон покидает Москву · 1812",y:"1812",d:"Великая армия бежит из Москвы — русская сатира рисует непобедимого беглецом."},
  "10-13":{t:"Политическая эмблема: свинья, ворон, крокодил",d:"Свинья, ворон, крокодил — звериный код сатиры рисовал политика зверем, чтобы бить без имён."},
  "10-14":{t:"Смещение Хрущёва · 1964",y:"1964",d:"Смещение Хрущёва свернуло оттепельную сатиру — смеяться снова стало опасно."},
  "10-15":{t:"«Жена-солдатка» — лубок о солдатской доле",d:"Народная картинка рисовала солдатскую долю глазами жены — честнее любой сводки."},
  "10-16":{t:"Ян Розен · 1854–1936",y:"1854",d:"Розен рисовал и империю, и новое время — его лист зафиксировал перемены."},
  "10-17":{t:"Сергей Булаковский · 1880–1937",y:"1880",d:"Булаковский рисовал между двумя эпохами — и его линия помнит обе."},
  "10-18":{t:"Стяпас Жукас · 1904–1946",y:"1904",d:"Жукас смешил советскую Прибалтику — смех на окраине империи звучал по-своему."},
  "10-19":{t:"Подпись под карикатурой: одностишие и эпиграмма",d:"Подпись Демьяна Бедного под рисунком била точнее самого рисунка."},
  "10-20":{t:"Международный день повара",d:"Кастрюля, поварёшка, борщ — карикатура века рисовала кухню с улыбкой."},
  "10-21":{t:"Политический портрет",d:"Парадный портрет льстил, карикатурный говорил правду в лицо: подбородок и прищур становились приговором."},
  "10-22":{t:"Карибский кризис · 1962",y:"1962",d:"Мир стоял на краю — и карикатура рисовала ракеты, примеряя страх к смеху."},
  "10-23":{t:"Современный шарж",d:"Современный шарж рисуют с натуры — и публикуют быстрее, чем газета успевает выйти."},
  "10-24":{t:"Инкерманское сражение · 1854",y:"1854",d:"Инкерман обернулся трагедией — карикатура рисовала героев и бездарное начальство."},
  "10-25":{t:"День автомобилиста",d:"Баранка, дорога, пробка — карикатура века рисовала шофёра и гаишника."},
  "10-26":{t:"Фельетон: сатира без рисунка",d:"Тэффи и Аверченко смешили словом рядом с карикатурой — линия и текст били в паре."},
  "10-27":{t:"«Агит-лубок» и окна Гражданской войны",d:"Лубок Гражданской войны переучился на агитацию — народная картинка стала плакатом."},
  "10-28":{t:"Международный день анимации",d:"Мультик ожил — и неподвижный шарж впервые задышал на экране."},
  "10-29":{t:"Сатира и философия",d:"Сатира вышла в философию — смех стал способом спросить о главном."},
  "10-30":{t:"Валерий Межлаук · 1893–1938",y:"1893",d:"Межлаук рисовал агитплакат — его лист бил по врагу быстрее передовицы."},
  "10-31":{t:"День сантехника",d:"Праздник тех, кто чинит трубы, — разводной ключ стал героем карикатур."},
  "11-01":{t:"Николай Иевлев · 1834",y:"1834",d:"Иевлев рисовал в николаевскую пору, когда цензура только училась запрещать — его смех опережал запреты."},
  "11-02":{t:"Александр Лебедев · 1826",y:"1826",d:"Лебедев смешил до журнального бума — когда журналов не было, сатира жила в альбомах и умела ждать."},
  "11-03":{t:"Дмитрий Моор · 1883–1946",y:"1883",d:"«Ты записался добровольцем?» — плакат Моора стал голосом эпохи и заговорил громче любой газеты."},
  "11-04":{t:"День народного единства",d:"Праздник собрал страну — а сатира честно рисовала, где народ вместе, а где врозь."},
  "11-05":{t:"Александр Заковряшин · 1899",y:"1899",d:"Заковряшин рисовал на сломе эпох — его лист успел сказать и о старом, и о новом."},
  "11-06":{t:"Ольга Лишева · 1889",y:"1889",d:"Лишева пробилась в мужской цех смеха — её лист добавил сатире женский взгляд."},
  "11-07":{t:"Парад на Красной площади · 1941",y:"1941",d:"Парад ушёл с Красной площади прямо на фронт — и сатира пошла в бой вместе с армией."},
  "11-08":{t:"Михаил Чемоданов · 1856–1908",y:"1856",d:"Чемоданов рисовал время без телевизора — его лист был тогдашней новостной лентой."},
  "11-09":{t:"Декрет о печати · 1917",y:"1917",d:"Декрет закрыл оппозиционную печать — сатире пришлось пережить первую зиму без свободы."},
  "11-10":{t:"Смерть Брежнева · 1982",y:"1982",d:"Смерть Брежнева закрыла эпоху застоя — карикатура тут же вспомнила всё, что не смела рисовать."},
  "11-11":{t:"Вениамин Ромов · 1881",y:"1881",d:"Ромов начинал при старом порядке и продолжал при новом — сатира шла за ним через перелом."},
  "11-12":{t:"Александр Силич · 1901",y:"1901",d:"Силич рисовал в первые советские годы — смех на его глазах учился новому языку."},
  "11-13":{t:"Валериан Черни · 1855",y:"1855",d:"Черни рисовал быт и нравы — его лист рассказал о людях, которые обходились без гаджетов."},
  "11-14":{t:"Карикатура одной линией",d:"Одна линия рождает характер — лаконичный приём, на котором полвека держалась бытовая сатира."},
  "11-15":{t:"Фронтовой шарж",d:"Шарж на войне грел не хуже махорки — фронтовая карикатура смешила бойцов между боями."},
  "11-16":{t:"День проектировщика",d:"Чертёж, ватман, кульман — карикатура века рисовала проект и смеялась над сметой у доски."},
  "11-17":{t:"Современная политическая карикатура",d:"Политическая карикатура переехала из газеты в ленту — и научилась бить быстрее новостей."},
  "11-18":{t:"Синопское сражение · 1853",y:"1853",d:"Синоп начал Крымскую войну победой — русский флот разбил турок, а сатира прославила героев."},
  "11-19":{t:"Владимир Андерсон · 1849",y:"1849",d:"Андерсон рисовал нравы второй половины XIX века — его лист рассказал о городе и человеке."},
  "11-20":{t:"Всемирный день ребёнка",d:"Дети, школа, мир — карикатура века рисовала детство и улыбалась над партой."},
  "11-21":{t:"День бухгалтера",d:"Цифры, счёты, отчёт — карикатура рисовала бухгалтерию и смеялась над припиской у абака."},
  "11-22":{t:"День психолога",d:"Кушетка, тест, диагноз — карикатура рисовала душу и смеялась в кабинете над сеансом."},
  "11-23":{t:"Валерий Каррик · 1869–1943",y:"1869",d:"Каррик рисовал русские сказки — в его листах смех уживался с волшебством."},
  "11-24":{t:"Оскар Каллис · 1892",y:"1892",d:"Каллис рисовал на рубеже эпох — его лист сохранил смех уходящего времени."},
  "11-25":{t:"Челли · 1888",y:"1888",d:"Челли подписывался коротко — за псевдонимом прятался почерк настоящего мастера."},
  "11-26":{t:"Александра Хотяинцева · 1865",y:"1865",d:"Хотяинцева рисовала друзей и эпоху Серебряного века — от её улыбки остался шарж на время."},
"11-27":{t:"Медведь, которого забрали назад",d:"Интернет вернул медведя в народную культуру: он снова мем, талисман и шутка, а не только грозный символ."},
  "11-28":{t:"Саргис Оганесян · 1884",y:"1884",d:"Оганесян смешил в начале века — от его смеха остался почерк мастера."},
  "11-29":{t:"День матери",d:"Мама, дом, забота — карикатура века рисовала семью и улыбалась вместе с мамами."},
  "11-30":{t:"Начало Зимней войны · 1939",y:"1939",d:"Зимняя война началась в мороз — сатира рисовала «белую войну» в снегах и стуже."},
  "12-01":{t:"Разгром выставки в Манеже · 1962",y:"1962",d:"Хрущёв разнёс авангардистов в Манеже — с этого скандала началась эпоха подпольных выставок и смеха в подполье."},
  "12-02":{t:"Лев Ваксель · 1811–1885",y:"1811",d:"Ваксель рисовал в николаевскую пору, когда смех был привилегией салонов, — его альбомы сохранили почерк эпохи."},
  "12-03":{t:"День юриста",d:"Карикатура века рисовала Фемиду с весами и мантией — суд на листах то вершит правосудие, то оборачивается фарсом."},
  "12-04":{t:"Журнальная сатира 1905 года",d:"Революция 1905 дала сатире голос — журнальный смех стал оружием и вышел тиражом в сотни тысяч."},
  "12-05":{t:"День добровольца (волонтёра)",d:"Карикатура рисовала добровольца с улыбкой — смех шёл рядом с теми, кто помогает по зову сердца."},
  "12-06":{t:"Типографика и плакат",d:"Типографика превращала шутку в плакат — буква, линия и цвет били точнее любой подписи."},
  "12-07":{t:"Сатира нравов: город и быт",d:"Сатира нравов ловила город за быт — лист показывал эпоху без гаджетов, в которой узнавал себя каждый прохожий."},
  "12-08":{t:"Агитационный плакат",d:"Агитплакат кричал громче газеты — одна картинка с подписью поднимала страну в поход."},
  "12-09":{t:"Декабрьское восстание · 1905",y:"1905",d:"Баррикады на Пресне стали последним аккордом 1905-го — сатира провожала восстание надеждой и разгромом."},
  "12-10":{t:"Современный плакат",d:"Плакат пережил эпоху бумаги — сегодня он бьёт с экрана и со стены сразу в миллион глаз."},
  "12-11":{t:"Журнальный шарж: одна деталь",d:"Журнальный шарж ловил знаменитость за один штрих — читатель узнавал лицо раньше, чем дочитывал подпись."},
  "12-12":{t:"Алексей Афанасьев · 1850–1920",y:"1850",d:"Афанасьев рисовал потешные листки ярмарки — смех жил на базарах раньше, чем попал в журналы."},
  "12-13":{t:"От карикатуры к комиксу",d:"Карикатура однажды растянулась в серию кадров — так из одной шутки родился целый комикс."},
  "12-14":{t:"Восстание декабристов · 1825",y:"1825",d:"Первый залп русской свободы на Сенатской — сатира и воспевала декабристов, и оплакивала их каторгу."},
  "12-15":{t:"Цифровой шарж",d:"Цифровой шарж рождается за секунды на планшете — художником шаржа теперь может стать каждый."},
  "12-16":{t:"Сатира народов: один журнал на всех",d:"Сатира народов соединяла смех разных республик — общий журнал смеялся на одном языке."},
  "12-17":{t:"Убийство Распутина · 1916",y:"1916",d:"Распутина рисовали задолго до той ночи на Мойке — сатира предсказала тёмного старца раньше, чем грянул выстрел."},
  "12-18":{t:"Сатира без редактора",d:"Современная сатира бьёт без цензуры и редактора — смех стал быстрее, острее и ближе к человеку."},
  "12-19":{t:"Мем-культура",d:"Мем — это карикатура, ужавшаяся до одной картинки с подписью, — смех разлетается быстрее, чем успеваешь переслать."},
  "12-20":{t:"Шипка: завершение обороны · 1877",y:"1877",d:"Ледяная Шипка держала оборону зимой — карикатура рисовала стужу и стойкость русских на перевале."},
  "12-21":{t:"Зимнее солнцестояние",d:"Самая длинная ночь года — карикатура рисовала тьму и свет, в которых шутка прятала надежду."},
  "12-22":{t:"День энергетика",d:"Карикатура века рисовала электрификацию — ток и лампочка несли в каждый дом и свет, и смех."},
  "12-23":{t:"Политическая сатира: лист против передовицы",d:"Политическая сатира била власть в лоб — лист с подписью был острее любой передовицы."},
  "12-24":{t:"Сказочная иллюстрация-шарж",d:"Сказочная иллюстрация соединилась с шаржем — знакомый зверь на листе вдруг получает человечье лицо."},
  "12-25":{t:"Ввод войск в Афганистан · 1979",y:"1979",d:"Война вошла в страну под Новый год — сатира рисовала то, о чём молчали газеты."},
  "12-26":{t:"Распад СССР · 1991",y:"1991",d:"В один день страна закончилась, а смех остался — сатира провожала империю и училась говорить свободно."},
  "12-27":{t:"День спасателя",d:"Карикатура рисовала спасателей между вызовами — смех грел тех, кто вытаскивает людей из огня."},
  "12-28":{t:"Николай Легат · 1869–1937",y:"1869",d:"Легат рисовал балет шаржем — смех увидел сцену с изнанки, где пуанты и позы смешнее пачек."},
"12-29":{t:"Сборка линии: весь медведь за пять веков",d:"Все выпуски маршрута сходятся в одну линию: посетитель видит, как один и тот же зверь менял смысл пять веков подряд."},
  "12-30":{t:"Образование СССР · 1922",y:"1922",d:"СССР родился под Новый год — сатира, которой предстояло жить в нём семьдесят лет, встретила союз улыбкой."},
  "12-31":{t:"Новый год: год смехом",d:"Ёлка, Дед Мороз и двенадцать месяцев смеха в одной картинке — карикатура провожает год улыбкой."}
};
